const m="compassion",g=[{id:"compassion-neff-definition",title:"Neff · Che cos’è la compassione verso di sé? · Dossier C11",url:"https://self-compassion.org/what-is-self-compassion/",type:"guidance",finding:"Il modello unisce gentilezza verso di sé, umanità condivisa e riconoscimento consapevole della difficoltà. Compassione tenera e ferma sono descrizioni pratiche di conforto, protezione e azione.",limitation:"Pagina di definizione, non prove su un meccanismo isolato o un trattamento. L’autostima può dipendere dai risultati, ma non è sempre così. Non è obbligatorio provare calore."},{id:"compassion-mindful-self-compassion-rct",title:"Neff e Germer · 2013 · Studio Mindful Self-Compassion · Dossier C05",url:"https://doi.org/10.1002/jclp.21923",type:"research",finding:"52 adulti assegnati casualmente a un programma di otto settimane o a una lista d’attesa. I confronti tra i gruppi alla fine del programma lo favorivano su varie misure. Incontri e ritiro richiedevano una pratica consistente.",limitation:"Piccolo studio su un programma completo condotto dagli autori, non su una pausa o lettera. A un anno rispondevano 15 persone, senza controllo contemporaneo. Non dimostra effetti comparativi mantenuti per tutti."},{id:"compassion-gilbert-cft",title:"Gilbert · 2014 · Terapia focalizzata sulla compassione · Dossier C07",url:"https://doi.org/10.1111/bjc.12043",type:"research",finding:"La revisione clinica e teorica descrive minaccia, spinta ad agire e rasserenamento attraverso i legami come modello funzionale, con pratiche focalizzate sulla compassione.",limitation:"Non tre interruttori anatomici né prova dell’effetto isolato di un’espirazione o di immagini mentali. Sicurezza pratica, risorse e bisogni materiali possono contare. Le pratiche sul sentirsi al sicuro possono dare fastidio."},{id:"compassion-tangney-moral-emotions",title:"Tangney, Stuewig e Mashek · 2007 · Emozioni morali · Dossier C08",url:"https://doi.org/10.1146/annurev.psych.56.091103.070145",type:"research",finding:"La vergogna rivolta all’intera persona è spesso legata al ritiro o a risposte difensive. Il senso di colpa rivolto al comportamento può accompagnare empatia e riparazione.",limitation:"Revisione narrativa, soprattutto osservativa. Sono tendenze, non leggi assolute. Il senso di colpa eccessivo può nuocere. La vergogna dopo un danno subito non dimostra colpevolezza né obbligo di scusarsi."},{id:"compassion-brown-shame-resilience",title:"Brown · 2006 · Teoria della resilienza alla vergogna · Dossier C09",url:"https://doi.org/10.1606/1044-3894.3483",type:"research",finding:"Dalle interviste a 215 donne è emersa una cornice che include riconoscere la vergogna, verificare le aspettative, trovare legami sicuri e darle un nome.",limitation:"Costruzione qualitativa di una teoria, non verifica controllata di un trattamento in quattro passi. Confidarti è facoltativo, solo con persone sicure e disponibili. Nessuna attenzione al corpo o rievocazione traumatica imposta."},{id:"compassion-improvement-motivation",title:"Breines e Chen · 2012 · Motivazione a migliorare · Dossier C06",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Quattro esperimenti hanno trovato motivazione a migliorare nel breve periodo. Dopo un test andato male, il gruppo con compassione studiava più a lungo di quello senza promemoria: 306,5 contro 203,2 secondi.",limitation:"I risultati al secondo test non miglioravano significativamente. Il confronto con l’autostima era inconcludente. Voler rimediare non significa averlo fatto. Non sono stati verificati cambiamento duraturo o repliche indipendenti preregistrate."},{id:"compassion-journal-guidance",title:"Neff · Diario di compassione verso di sé · Dossier C18",url:"https://self-compassion.org/exercises/exercise-6-self-compassion-journal/",type:"technique",finding:"Le indicazioni dell’autrice chiedono di riconoscere una difficoltà, il suo contesto umano e parole gentili, scrivendo ogni giorno per una settimana o più.",limitation:"Non prova di efficacia isolata né verifica della versione ODA. Anticipare la scrittura o accorciare la riflessione sono adattamenti. Puoi saltare o interrompere la scrittura se alimenta il disagio."},{id:"compassion-break-guidance",title:"Neff · Pausa di compassione verso di sé · Dossier C16",url:"https://self-compassion.org/exercises/exercise-2-self-compassion-break/",type:"technique",finding:"La procedura dell’autrice riconosce il dolore e l’umanità condivisa e propone parole gentili o un augurio. Le indicazioni originali includono un contatto di supporto con il proprio corpo.",limitation:"Non verifica isolata di efficacia né durata di due minuti dimostrata. ODA offre contatto facoltativo, esempi lievi, respiro normale, attenzione all’esterno e possibilità di fermarsi."},{id:"compassion-touch-trial",title:"Dreisoerner e colleghi · 2021 · Studio sul contatto con il proprio corpo · Dossier C14",url:"https://doi.org/10.1016/j.cpnec.2021.100091",type:"research",finding:"Il campione finale comprendeva 159 giovani adulti sani. Il contatto con il proprio corpo cambiava le risposte del cortisolo a uno stimolo stressante di laboratorio; stress riferito e frequenza cardiaca non differivano.",limitation:"Singolo studio preregistrato, con analisi modificata per i dati mancanti. Nessuna misura di ossitocina, garanzia di sollievo emotivo o efficacia clinica. Respiro normale e assenza di contatto sono adattamenti ODA."},{id:"compassion-kindness-review",title:"Zeng e colleghi · 2015 · Revisione sulla meditazione di gentilezza · Dossier C10",url:"https://doi.org/10.3389/fpsyg.2015.01693",type:"research",finding:"24 studi empirici con 1.759 partecipanti utilizzavano metodi diversi. Le stime dei sottogruppi pertinenti di gentilezza amorevole e compassione erano 0,424 e 0,286; la differenza non era significativa.",limitation:"Non 24 studi randomizzati né prova di una pratica vincente. Metodi variabili, studi iniziali e spesso controlli in lista d’attesa. Non stima gli effetti degli esercizi ODA di rasserenamento."},{id:"compassion-practice-safety",title:"Neff · Indicazioni per praticare la compassione verso di sé · Dossier C12",url:"https://self-compassion.org/self-compassion-practices/",type:"guidance",finding:"Le indicazioni dell’autrice distinguono un’intenzione gentile dal produrre sensazioni piacevoli e consigliano di ridurre o interrompere la pratica quando sopraffà.",limitation:"Consigli pratici, non una nuova diagnosi o un meccanismo fisiologico di “ritorno di fiamma” dimostrato. Attenzione all’esterno, supporto ordinario o interruzione possono sostituire un’attenzione interna che dà fastidio."},{id:"compassion-letter-guidance",title:"Neff · Indicazioni sulla lettera dal punto di vista di un amico · Dossier C17",url:"https://self-compassion.org/exercises/exercise-3-exploring-self-compassion-through-writing/",type:"technique",finding:"Le indicazioni dell’autrice descrivono il punto di vista di un amico premuroso, suggerimenti gentili per cambiare e il mettere da parte la lettera per rileggerla.",limitation:"Non verifica isolata di efficacia né durata convalidata di quindici minuti. Lo studio sul programma non isolava la lettera. Nessun racconto di sofferenza, calore, colpa o confidenza imposti."}];function a(i){const e=i.suggestions;return{schemaVersion:2,revision:2,id:i.id,courseId:m,locale:"it",title:i.title,goal:i.goal,minutes:{learning:6,suggestedAction:e.minutes[0],review:2},direction:{hook:i.hook,reason:{id:`${i.id}-reason`,label:i.reason,kind:"text",maxLength:160,optional:!0,suggestions:i.reasons},why:{id:`${i.id}-why`,label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:`${i.id}-cost`,label:"Che cosa ti costa continuare con questo comportamento?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:i.paragraphs,example:i.example},move:{invitation:i.invitation,instructions:i.instructions,prompts:[],suggestions:e,suggested:{action:e.action[0],minimum:e.minimum[0],minutes:e.minutes[0],cueHint:e.cue[0],placeHint:e.place[0],obstacleHint:i.obstacle,fallbackHint:e.fallback[0],observationHint:e.observation[0]},stopRule:i.stop,accessibleAlternative:i.accessible},result:{question:i.result,observationPrompt:i.observation},judgment:{primary:i.scenario},carry:{takeaway:i.takeaway,followUp:{questionId:`${i.id}-return`,question:i.follow,observationPrompt:i.followObservation,adjustmentPrompt:"Che cosa renderebbe il prossimo tentativo fattibile nella tua vita quotidiana?"}},goDeeper:{sections:i.depth,sourceIds:i.sources}}}const s=a({title:"Hai sbagliato ancora? Correggi l’errore senza insultarti",goal:"Scegli una difficoltà gestibile, descrivila senza insultarti e fai un passo utile per rimediare, lavorare o chiedere supporto.",hook:"La voce critica dice di tenerti in riga. Dopo l’ultimo insulto, che cosa hai fatto di utile?",reason:"Quale risposta utile rimandi continuando a criticarti?",reasons:["Correggere un errore reale","Tornare a un lavoro utile","Chiedere supporto prima"],paragraphs:["Cura e impegno possono andare insieme. In un esperimento dopo un test andato male, gli studenti che ricevevano un invito alla compassione studiavano più a lungo di quelli senza promemoria. I voti successivi non miglioravano significativamente. Si parla di impegno a breve termine, non di risultati garantiti.","Scegli una difficoltà quotidiana da seguire nel corso. Tieni il fatto, togli l’insulto: “Ho sottostimato il tempo”, non “Non valgo niente”. Poi correggi, torna al lavoro o chiedi supporto. Rimedia al danno che hai causato; proteggiti da quello subito. Sentirti più gentile è facoltativo. Azione, segnale di inizio ed esito sono le parti dell’esperimento che porterai avanti."],example:{title:"Daniele comunica una nuova data",text:"Alle 17 Daniele vede che ha sottostimato il tempo per la relazione. Sostituisce “idiota superficiale” con il fatto. Dalla scrivania invia una nuova data realistica e aggiunge un margine alla prossima stima. Il responsabile è deluso. Daniele annota aggiornamento e correzione. Gli dispiace ancora per il ritardo, ma ha iniziato a rimediare."},invitation:"Scegli una difficoltà gestibile. Tieni il fatto, poi fai qualcosa di utile invece di insultarti.",instructions:["Indica il fatto senza giudicare il tuo valore.","Fai un passo appropriato per rimediare, lavorare o chiedere supporto."],suggestions:{action:["Invia una nuova data realistica","Correggi un errore reale nel lavoro","Chiedi un aiuto pratico specifico"],minimum:["Invia una frase di aggiornamento basata sui fatti","Correggi un elemento concreto","Indica un bisogno di supporto"],cue:["Dopo aver verificato la stima sbagliata","Alla prossima difficoltà gestibile"],place:["Alla mia scrivania di lavoro","In una conversazione scritta sicura"],fallback:["Chiedi aiuto per stimare il lavoro","Scegli un modo più sicuro per chiedere supporto"],observation:["L’aggiornamento o la correzione fatti","La risposta che ho ricevuto, se è arrivata"],minutes:[3,2,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Mi insulto invece di affrontare l’errore",stop:"Scegli una difficoltà quotidiana. Fermati se provi disagio; cerca supporto se persiste o diventa opprimente.",accessible:"Usa parole neutre, il tuo modo abituale di comunicare o assistenza. Non servono calore, attenzione al corpo o confidenze.",result:"Hai fatto il passo utile che avevi scelto?",observation:"Che cosa hai corretto, chiesto o fatto davvero?",scenario:{scenario:"Daniele ha mancato una scadenza perché ha sottostimato il lavoro. Adesso può comunicare una data realistica e cambiare la stima.",question:"Quale risposta unisce cura e responsabilità?",options:[{text:"Riconoscere la stima sbagliata senza insultarsi, inviare la data realistica e modificare il modo di fare la prossima stima.",feedback:"Mantiene visibili le conseguenze reali e inizia a rimediare. Daniele può dispiacersi per l’errore, dare informazioni utili e migliorare il piano. Essere gentile con sé non significa giustificare il ritardo.",id:"update-and-adjust"},{text:"Prendersi la serata libera e preparare un aggiornamento per il gruppo quando la vergogna sarà abbastanza gestibile da parlarne.",feedback:"Riposare può servire, ma l’aggiornamento è possibile e necessario adesso. Aspettare che la vergogna cali lascia gli altri senza informazioni. Comunica la data realistica, poi scegli il recupero di cui hai bisogno.",id:"wait-for-shame"},{text:"Spiegare quanto si sente male per il ritardo e promettere una nuova data quando avrà più chiarezza sul lavoro.",feedback:"Un dispiacere sincero può accompagnare le scuse, ma non sostituisce le informazioni che Daniele ha già. Comunica la data realistica e correggi la stima, senza dare spazio soprattutto all’autopunizione.",id:"explain-regret"}],id:"compassion-1-missed-estimate",bestOptionId:"update-and-adjust"},takeaway:"Mantieni i fatti e gli standard che vuoi rispettare. Mostra la cura nel prossimo passo utile.",follow:"Parole eque hanno sostenuto un passo utile, sono rimaste parole o hanno indicato un bisogno di supporto o pausa?",followObservation:"Indica l’aggiornamento, la correzione o la richiesta fatti; segnala se non erano ancora possibili.",depth:[{heading:"Più studio non significava voti migliori",paragraphs:["Breines e Chen hanno condotto quattro esperimenti sulla compassione verso di sé e sulla motivazione a migliorare. Dopo il test andato male, il gruppo con compassione studiava in media 306,5 secondi, contro 203,2 nel gruppo senza promemoria. Il confronto con rassicurazioni sull’autostima era inconcludente; i risultati al secondo test non differivano significativamente. L’esperimento su una trasgressione misurava la motivazione a rimediare, non il danno effettivamente riparato. [C06: compassion-improvement-motivation]","Questi esperimenti brevi coinvolgevano soprattutto studenti; l’articolo includeva anche un campione di adulti online. Non dimostrano cambiamento duraturo o l’effetto delle frasi di questa lezione. La cura può accompagnare l’impegno, ma una frase equa non garantisce motivazione, prestazione o riparazione. L’azione successiva è un adattamento ODA. Riferisci direttamente il comportamento, compresi una risposta inutile, una correzione incompleta o un’occasione assente. Inviare una nuova data prova che hai aggiornato gli altri, non che hai finito il lavoro in ritardo."]},{heading:"Una difficoltà, una risposta che prosegue",paragraphs:["Neff descrive la compassione verso di sé come gentilezza, umanità condivisa e riconoscimento consapevole della difficoltà. Non richiede di dimenticare un errore o approvare comportamenti dannosi. È una definizione e un modello usato nella pratica, non tre meccanismi dimostrati separatamente. [C11: compassion-neff-definition] Qui basta un rispetto sobrio: dire che cosa è successo e scegliere ciò che aiuta ad affrontarlo.","Proseguendo, mantieni la stessa difficoltà gestibile o lo stesso schema ricorrente. Le prossime lezioni affinano il supporto all’azione, senza aggiungere un obbligo di sentirti bene. Una correzione serve dove hai davvero sbagliato. Supporto o protezione servono dove hai subito danni o il lavoro supera le tue risorse. Non scusarti per qualcosa che non hai fatto solo per adattarti all’esercizio. Puoi annotare un tentativo di rimediare, un lavoro ripreso, una richiesta di supporto o una pausa appropriata. Un piano resta tale finché non riferisci un’azione; la risposta altrui resta fuori dal tuo controllo."]}],id:"compassion-1",sources:["compassion-improvement-motivation","compassion-neff-definition"]}),l=a({title:"Sbagliano tutti. La tua delusione merita comunque attenzione",goal:"Aggiungi il supporto mancante alla tua risposta alla stessa difficoltà, poi fai il minimo utile già scelto.",hook:"“Sbagliano tutti” può diventare un modo per liquidarti. Che cosa hai lasciato fuori dalla tua risposta?",reason:"Che cosa smetti di affrontare quando liquidi la tua delusione?",reasons:["Riconoscere ciò che ha fatto male","Non trattarmi come l’unica persona difettosa","Riprendere senza liquidare la difficoltà"],paragraphs:["Il modello di Neff unisce il riconoscere la difficoltà, vedere che altri la vivono e rispondere in modo utile. “Sbagliano tutti, smettila di farne un dramma” riconosce l’umanità condivisa, ma liquida il dolore. Dare un nome al dolore senza offrire supporto lascia fuori un’altra parte.","Nella stessa difficoltà, aggiungi una frase neutra per la parte mancante. Può bastare “Sono delusa e posso rivedere una domanda”. L’autostima può legarsi ai risultati, ma non è sempre così. In questa pratica non devi confrontare il tuo valore con nessuno. Poi fai il minimo utile già scelto, oppure cerca un supporto appropriato."],example:{title:"Irene rivede una domanda",text:"Dopo cena Irene rivede l’errore d’esame scelto ieri. “Sbagliano tutti” le permetteva di non ammettere la delusione. Al tavolo della cucina aggiunge: “Fa male, e posso aiutarmi a capire una domanda”. La rivede per due minuti. Il risultato ancora non le piace e serve esercizio. Annota la revisione, senza dare un voto alla fiducia."},invitation:"Aggiungi il supporto mancato nella risposta precedente. Usalo con la stessa azione utile.",instructions:["Riconosci la difficoltà senza esagerarla o liquidarla.","Fai il minimo utile già scelto, oppure cerca supporto appropriato."],suggestions:{action:["Rivedi una domanda a cui hai risposto male","Correggi il punto del lavoro che hai scelto","Invia la richiesta di supporto prevista"],minimum:["Lavora su una domanda dell’esercizio","Correggi un elemento concreto","Fai una richiesta di supporto"],cue:["Dopo cena, al momento della revisione","Al segnale già scelto per la difficoltà"],place:["Al tavolo della cucina","Nel mio luogo sicuro per studiare"],fallback:["Chiedi aiuto per la domanda","Usa parole neutre e riduci il passo"],observation:["La frase di supporto e l’azione usate","Dove mi serve ancora aiuto"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Liquido la difficoltà invece di aiutarmi ad affrontarla",stop:"Salta i ricordi dolorosi e cerca supporto se la pratica diventa opprimente.",accessible:"Usa parole neutre in silenzio, scrivi, usa la lingua dei segni o chiedi assistenza. Non servono calore o confronti con altri.",result:"Hai fatto il minimo utile con il supporto aggiunto?",observation:"Quale supporto hai aggiunto e che cosa hai fatto davvero?",scenario:{scenario:"Irene liquida la delusione per l’esame con “Sbagliano tutti”. È riposata, ha cinque minuti liberi e una domanda già individuata, pronta da rivedere. Il turno serale non lascerà altro tempo per studiare.",question:"Quale risposta sostiene la revisione possibile adesso?",options:[{text:"Riconoscere la delusione, fare una breve pausa dallo studio adesso e tenere la domanda pronta per dopo il turno.",feedback:"Una pausa protegge le energie quando serve. Qui Irene è riposata e dopo il turno non avrà tempo per studiare. Può affrontare la domanda disponibile adesso e prevedere recupero intorno al turno.",id:"break-and-review-later"},{text:"Riconoscere la delusione e usare i cinque minuti per organizzare un quadro degli argomenti su cui serve più esercizio.",feedback:"Un quadro generale aiuta se le priorità sono poco chiare. Questa domanda è già individuata e pronta. Affrontarla adesso mostrerà le difficoltà rimaste, che potranno guidare una revisione più ampia dopo.",id:"organize-review-topics"},{text:"Riconoscere la delusione e la difficoltà condivisa, poi rispondere con equità mentre rivede la domanda già preparata.",feedback:"L’umanità condivisa non cancella la delusione di Irene. Questa risposta mantiene visibile la sensazione e sostiene un’azione utile. Non richiede confronti di valore né sollievo immediato per rendere valida la revisione.",id:"acknowledge-and-review"}],id:"compassion-2-dismissed-disappointment",bestOptionId:"acknowledge-and-review"},takeaway:"La difficoltà condivisa può ridurre l’isolamento. Non cancella ciò che ti serve adesso.",follow:"Quale supporto mancava? Aggiungerlo ha cambiato il prossimo passo utile che hai fatto?",followObservation:"Indica il supporto mancante e l’effetto, oppure se l’hai saltato o l’effetto resta sconosciuto.",depth:[{heading:"Una definizione non dimostra tre ingredienti separati",paragraphs:["La definizione di Neff unisce gentilezza verso di sé, umanità condivisa e riconoscimento consapevole della sofferenza. Sono nomi di un modello. La pagina dell’autrice non dimostra che ogni componente isolata causi autonomamente un miglioramento clinico. Non definisce nemmeno tutta l’autostima come competizione. Il valore personale può diventare dipendente dai risultati o dal confronto, ma è uno schema possibile, non l’intero concetto. [C11: compassion-neff-definition]","Esamina questi tre aspetti della tua risposta, senza dare un voto alla tua umanità. Hai riconosciuto la difficoltà? Hai evitato di usarla come prova che soltanto tu sei difettoso? Hai offerto una risposta utile? Se il linguaggio affettuoso suona falso, la frase può essere neutra e rispettosa. Mantieni l’azione scelta nella lezione precedente. È una breve applicazione ODA: puoi riferire ciò che hai fatto con quel supporto, non una diagnosi o un punteggio convalidato delle componenti."]},{heading:"Il diario sostiene l’azione, senza sostituirla",paragraphs:["Il diario di compassione verso di sé dell’autrice chiede di riconoscere una difficoltà, il suo contesto umano e parole gentili. Propone di scrivere ogni giorno per una settimana o più, di solito la sera. Le indicazioni spiegano come viene insegnata la pratica; non dimostrano un effetto clinico isolato o una durata ottimale della scrittura. [C18: compassion-journal-guidance] Questa lezione propone una verifica più breve e facoltativa per l’esperimento che stai portando avanti.","Scrivi soltanto se aiuta. Puoi rispondere in silenzio, usare comunicazione assistita o conservare i dettagli altrove. Se la riflessione alimenta il rimuginio, cambia momento o rinuncia a scrivere. Una pagina di diario è preparazione quando lo scopo è rivedere una domanda, correggere o chiedere supporto. Puoi annotarla come preparazione, ma non prova che l’azione successiva sia avvenuta. Annota la domanda affrontata, la correzione fatta o la richiesta inviata. Le segnalazioni urgenti e le procedure di sicurezza stabilite non devono mai aspettare una riflessione personale."]}],id:"compassion-2",sources:["compassion-neff-definition","compassion-journal-guidance"]}),c=a({title:"Ancora turbato dopo la pausa? Scegli come aiutarti",goal:"Usa una pausa di supporto facoltativa prima della stessa azione utile, senza richiedere sollievo per completarla.",hook:"Hai fatto una pausa, ma la critica brucia ancora. Quale risposta gestibile ti aiuterebbe adesso?",reason:"Che cosa resta incompiuto mentre aspetti di sentirti calmo?",reasons:["Rispondere a osservazioni utili","Scegliere supporto se mi sento sopraffatto","Riprendere senza aspettare la calma"],paragraphs:["Una pausa di compassione verso di sé riconosce la difficoltà, l’umanità condivisa e una risposta utile. È un’indicazione dell’autrice. Lo studio ha esaminato un programma di otto settimane, non una pausa di due minuti. La verifica a un anno era incompleta e senza gruppo di confronto.","Nella stessa difficoltà quotidiana, prova “È difficile; che cosa aiuterebbe?”. Toccarti, chiudere gli occhi, concentrarti sul corpo e provare calore sono facoltativi. Respira normalmente; se preferisci, guarda intorno a te. Fai il minimo utile, adattalo o chiedi supporto. Fermati se il disagio aumenta. La pausa prepara una scelta; annota l’azione fatta davvero."],example:{title:"Samuele risponde alle osservazioni",text:"Alle 15 Samuele riceve osservazioni difficili sulla bozza che sta migliorando. Fa una pausa usando soltanto parole: “È difficile; che cosa aiuterebbe adesso?”. Toccarsi dà fastidio, quindi lo evita. Ancora turbato, corregge alla scrivania un errore segnalato. Annota la correzione. La bozza richiede un altro passaggio e la sensazione non è scomparsa."},invitation:"Se serve, fai una breve pausa di supporto. Poi scegli la stessa azione gestibile, un adattamento o supporto.",instructions:["Scegli una difficoltà quotidiana lieve, senza forzare i ricordi.","Fai un passo utile se il contesto è adatto."],suggestions:{action:["Correggi un errore concreto nella bozza","Invia l’aggiornamento che hai scelto, riportando i fatti","Fai la richiesta di supporto prevista"],minimum:["Correggi un errore segnalato","Invia una frase di aggiornamento","Indica un bisogno di supporto"],cue:["Dopo osservazioni difficili da accettare","Al segnale già scelto per la difficoltà"],place:["Alla scrivania, in sicurezza","In un luogo tranquillo e familiare"],fallback:["Guarda all’esterno e usa parole neutre","Fermati e chiedi un supporto utile"],observation:["Il prossimo gesto di cura fatto davvero","Se mi sono fermato quando ho provato fastidio"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Aspetto che la pausa faccia sparire la sensazione",stop:"Puoi evitare di toccarti o di richiamare ricordi. Fermati se provi disagio e cerca supporto quando serve.",accessible:"Tieni gli occhi aperti, respira normalmente e osserva la stanza. Non servono attenzione al corpo o calore.",result:"Hai fatto il prossimo gesto di cura che avevi scelto?",observation:"Hai agito, adattato, interrotto o chiesto supporto?",scenario:{scenario:"Dopo le osservazioni, Samuele fa una pausa confortevole. Resta turbato, ma può correggere in sicurezza un errore chiaro della bozza in due minuti. Mancano quattro minuti all’incontro per rivederla.",question:"Quale scelta rispetta lo scopo della pausa?",options:[{text:"Fare un’altra pausa di due minuti, poi prevedere la correzione dopo l’incontro per non lavorare di fretta sulla bozza.",feedback:"Più tempo può aiutare quando il lavoro supera le possibilità attuali. Questa correzione sicura è fattibile prima dell’incontro. Può provare il minimo disponibile pur turbato, fermandosi se si sente sopraffatto.",id:"pause-and-correct-later"},{text:"Correggere l’errore chiaro pur sentendosi turbato e scegliere invece supporto se la risposta diventa troppo difficile da gestire.",feedback:"Il sollievo non è il risultato richiesto. La pausa sostiene una scelta fattibile, compreso il supporto quando serve. Samuele può annotare la correzione reale senza sostenere che l’emozione sia cambiata.",id:"manageable-correction"},{text:"Rivedere prima le priorità più ampie delle osservazioni, poi fissare la correzione chiara per la prossima sessione sulla bozza.",feedback:"Una revisione ampia può mostrare ciò che conta di più. Qui una correzione necessaria è già chiara e fattibile prima dell’incontro. Può farla adesso e rivedere separatamente le priorità più ampie.",id:"review-broader-priorities"}],id:"compassion-3-upset-after-pause",bestOptionId:"manageable-correction"},takeaway:"Una pausa di cura sostiene una scelta. Non deve per forza farti sentire bene.",follow:"Dopo la pausa hai agito, adattato il passo, cercato supporto o avuto bisogno di fermarti?",followObservation:"Indica il passo fatto davvero e se hai usato o saltato la pausa.",depth:[{heading:"La pausa e il programma sono diversi",paragraphs:["Le istruzioni di Neff per una pausa di compassione verso di sé riconoscono il dolore, ricordano che le difficoltà fanno parte della vita umana e propongono parole gentili o un augurio. Le indicazioni originali includono un contatto di supporto con il proprio corpo. Non dimostrano un’efficacia isolata o una durata di due minuti verificata. [C16: compassion-break-guidance] Qui toccarti e richiamare ricordi sono facoltativi; la risposta pratica è un adattamento ODA.","Lo studio Mindful Self-Compassion ha assegnato casualmente 52 adulti della comunità a un programma di otto settimane o a una lista d’attesa. Prevedeva incontri settimanali di due ore e un ritiro di quattro ore, incoraggiando una pratica quotidiana consistente. I risultati controllati alla fine favorivano il programma su varie misure. A un anno rispondevano soltanto 15 partecipanti del programma, senza un gruppo di controllo contemporaneo. Quella verifica non prova che i benefici rispetto al gruppo di confronto si siano mantenuti per tutti; lo studio non isolava la pausa. [C05: compassion-mindful-self-compassion-rct] Non usare l’effetto di un programma per giudicare questa piccola pausa personale."]},{heading:"Toccare il proprio corpo non garantisce sollievo",paragraphs:["Dreisoerner e colleghi hanno studiato un contatto facoltativo con il proprio corpo per confortarsi prima di un fattore di stress in laboratorio, in giovani adulti sani. Le risposte del cortisolo differivano, mentre stress riferito e frequenza cardiaca no. Lo studio non misurava ossitocina né dimostrava miglioramento clinico duraturo. Un risultato fisiologico non promette che ti sentirai meglio. [C14: compassion-touch-trial] Qui occhi aperti, assenza di contatto e respiro normale sono scelte di accessibilità e sicurezza, non il preciso protocollo studiato.","Puoi usare soltanto parole, scegliere espressioni neutre o osservare qualcosa fuori di te. Non devi avere contatto fisico con un’altra persona. Se un ricordo, toccarti o concentrarti su ciò che provi aumentano il fastidio, fermati senza forzarti a provare calore. Scegli un’attività semplice di supporto o un aiuto umano. Il prossimo gesto potrebbe essere una correzione, una richiesta di supporto o recupero. Annota che cosa hai fatto, rispetto al minimo scelto. Una pausa interrotta dà informazioni; non devi dimostrare di esserti impegnato abbastanza."]}],id:"compassion-3",sources:["compassion-break-guidance","compassion-mindful-self-compassion-rct","compassion-touch-trial"]}),p=a({title:"Lavori ancora? Proteggi ciò che stai sacrificando",goal:"Verifica i rischi reali. Metti in pratica un limite o chiedi supporto nello stesso esperimento.",hook:"Lavori anche stasera. Quale rischio reale va affrontato? Che cosa ti spinge a continuare?",reason:"Che cosa costa lavorare ancora? Quale rischio reale resta?",reasons:["Proteggere il recupero dopo il lavoro","Avere tempo per le persone care","Affrontare un bisogno reale di sicurezza"],paragraphs:["Il modello di Gilbert su minaccia, spinta ad agire e rasserenamento è una cornice clinica, non tre interruttori cerebrali. Chiediti se fare di più affronta un bisogno reale o prolunga un circolo. Protezione concreta e risorse possono cambiare la sicurezza; le rassicurazioni non le sostituiscono.","Riprendi la stessa difficoltà o abitudine. Se compare spesso troppo lavoro, verifica scadenze e conseguenze prima di scegliere quando staccare. Un pericolo reale richiede aiuto pratico. Respiro e immagini sono facoltativi; può bastare una pausa guardando all’esterno. Metti in pratica il limite o fai la richiesta senza pretendere calma, una casella di posta vuota o approvazione."],example:{title:"Marta stacca all’ora scelta",text:"Alle 21 Marta vede nelle annotazioni un altro episodio di lavoro fino a tardi. Non ci sono scadenze urgenti. Seduta alla scrivania, guarda la lampada, indica la prima priorità di domani e chiude le app di lavoro. La preoccupazione resta. Si prende il riposo previsto e annota il limite rispettato. Una mail incompleta aspetta il mattino."},invitation:"Verifica il rischio nello stesso comportamento. Metti in pratica un limite o chiedi supporto pratico.",instructions:["Verifica scadenze, sicurezza e responsabilità prima di scegliere un limite.","Metti in pratica un limite o chiedi supporto."],suggestions:{action:["Chiudi le app di lavoro all’ora scelta","Fai una richiesta pratica per la sicurezza","Comunica un limite di lavoro fattibile"],minimum:["Chiudi le app di lavoro e allontanati","Fai una richiesta di supporto","Indica un limite fattibile al lavoro"],cue:["All’ora che ho scelto per staccare","Quando si ripete la mia abitudine"],place:["Alla mia scrivania di lavoro","In un canale sicuro di supporto"],fallback:["Chiarisci una responsabilità davvero urgente","Chiedi aiuto per rendere sicuro il limite"],observation:["Se ho rispettato il limite scelto","Quale rischio reale si è presentato"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Continuo a lavorare finché la preoccupazione non sparisce",stop:"Interrompi l’attenzione al respiro o le immagini se danno fastidio. Un pericolo reale richiede protezione pratica e supporto.",accessible:"Resta seduto a occhi aperti, osservando la stanza e respirando normalmente. Non servono immagini o calore.",result:"Hai messo in pratica il limite o fatto la richiesta scelta?",observation:"Quale limite hai usato e quale conseguenza concreta è seguita?",scenario:{scenario:"Marta continua a lavorare per paura delle critiche. Ha verificato le scadenze: non resta nulla di urgente. Ha scelto un’ora per staccare e proteggere il recupero.",question:"Quale passo mette alla prova quel limite?",options:[{text:"Annotare la prima priorità di domani e chiudere le app di lavoro all’ora scelta, lasciando che la preoccupazione resti.",feedback:"Affronta il comportamento ricorrente e conserva il lavoro di domani. Marta può provare un limite fattibile senza finire ogni mail o imporre calma. Un rischio urgente reale richiederebbe una risposta diversa.",id:"priority-and-close"},{text:"Finire stasera il lavoro prioritario di domani, così da potersi fermare sapendo di averlo completato.",feedback:"Finire può sembrare più sicuro, ma nessuna scadenza urgente lo richiede. Prolunga lo stesso circolo che il limite affronta. Può tenere l’appunto sulla priorità e provare a fermarsi all’ora scelta.",id:"finish-tomorrow-task"},{text:"Chiudere le app dopo cinque minuti di controllo delle mail, per verificare di non avere trascurato una scadenza.",feedback:"Un ultimo controllo serve se l’urgenza è sconosciuta. Marta ha già verificato le scadenze. Un’altra occhiata ritarda il limite scelto: può annotare la priorità di domani e chiudere le app.",id:"scan-before-closing"}],id:"compassion-4-no-urgent-deadline",bestOptionId:"priority-and-close"},takeaway:"Verifica il rischio reale. Trasforma la cura in un limite, una risorsa o una richiesta concreta.",follow:"Hai provato il limite? Un nuovo rischio è comparso, è rimasto assente o resta incerto?",followObservation:"Quale tempo o risorsa hai protetto e quale conseguenza concreta è emersa?",depth:[{heading:"Una mappa clinica, non tre interruttori cerebrali",paragraphs:["La revisione clinica di Gilbert usa minaccia, ricerca di risultati o spinta ad agire e rasserenamento attraverso i legami come modello funzionale semplificato. Descrive la terapia focalizzata sulla compassione e gli esercizi usati nella pratica. Non dimostra sperimentalmente tre circuiti cerebrali distinti, un effetto isolato dell’espirazione o un interruttore letterale che spenga la minaccia. [C07: compassion-gilbert-cft] Respiro confortevole e immagini compassionevoli possono essere pratiche facoltative, con la possibilità immediata di fermarti.","Il modello non decide nemmeno se un pericolo sia reale. Problemi di casa, reddito insufficiente, salute o rapporti pericolosi possono richiedere risorse e cambiamenti concreti. Risorse e protezione possono incidere sulla sicurezza. Verifica che cosa otterresti davvero lavorando ancora in questa situazione. Se non resta una responsabilità urgente, un limite può essere una prova utile. Se resta un rischio, protezione o supporto possono essere la scelta di cura. Le annotazioni distinguono questi casi. Un appunto sulla priorità prepara l’uscita dal lavoro; chiudere le app e allontanarti la mette in pratica."]},{heading:"Nessuna pratica vincente, nessun calore obbligatorio",paragraphs:["Zeng e colleghi hanno esaminato 24 studi empirici con 1.759 partecipanti, con metodi di studio diversi. Nell’analisi di sottogruppi pertinente, la stima per la gentilezza amorevole era 0,424 e quella per la compassione 0,286. La differenza tra sottogruppi non era significativa: questi valori non stabiliscono una pratica migliore. Non mostrano nemmeno che la compassione sia priva di effetti, né stimano l’effetto di un esercizio ODA di rasserenamento. [C10: compassion-kindness-review]","Le indicazioni dell’autrice distinguono un’intenzione gentile dal produrre sensazioni piacevoli e consigliano di ridurre o interrompere la pratica quando sopraffà. [C12: compassion-practice-safety] Se preferisci, osserva qualcosa all’esterno, fai un’attività ordinaria o cerca supporto invece delle immagini. Non definire il fastidio come un meccanismo fisiologico di “ritorno di fiamma” o una nuova diagnosi. Qui osserviamo se hai messo in pratica il limite o fatto la richiesta concreta. La preoccupazione può restare dopo aver staccato; qualcuno può dissentire. Questi fatti aiutano ad adattare la prova, senza imporre calore."]}],id:"compassion-4",sources:["compassion-gilbert-cft","compassion-kindness-review","compassion-practice-safety"]}),u=a({title:"Ti vergogni? Verifica di chi è la responsabilità",goal:"Verifica la responsabilità nella stessa difficoltà, poi fai un passo per rimediare, proteggerti o chiedere supporto.",hook:"Stai evitando di rimediare a un danno che hai causato, o accettando una colpa altrui? Parti dai fatti.",reason:"Che cosa ignoreresti o accetteresti attribuendo male la colpa?",reasons:["Rimediare al danno che ho causato","Rifiutare una colpa ingiusta","Chiedere supporto in sicurezza"],paragraphs:["La vergogna rivolta all’intera persona è spesso legata a nascondersi o difendersi. Il senso di colpa rivolto al comportamento può accompagnare empatia e riparazione. Sono tendenze: il senso di colpa eccessivo può nuocere. Vergognarsi dopo un danno subito non prova di avere sbagliato.","Verifica che cosa hai fatto e se ha causato danni. Rimedia in proporzione ai danni reali; proteggiti o chiedi supporto per i maltrattamenti. Puoi nominare la sensazione privatamente e verificare le aspettative. Confidati solo se vuoi, con persone sicure e disponibili. Fai un passo adatto: riscrivere non basta a rimediare."],example:{title:"Gianni verifica la propria responsabilità",text:"A pranzo Gianni ripensa a una frase dura detta a un collega. Riconosce le parole e il loro effetto senza definirsi una cattiva persona. In un messaggio privato si scusa per quella frase e corregge l’informazione data. Il collega quel giorno non risponde. Gianni annota il passo per rimediare, senza chiedere rassicurazioni o perdono."},invitation:"Verifica i fatti nella stessa difficoltà. Rimedia al danno reale; altrimenti scegli protezione o supporto.",instructions:["Verifica la responsabilità prima di decidere se scusarti.","Fai un passo sicuro: rimedia, proteggiti o chiedi supporto."],suggestions:{action:["Rimedia al danno causato, basandoti sui fatti","Fai una richiesta sicura di supporto","Metti in pratica un limite che ti protegge"],minimum:["Rimedia a un danno che hai causato","Fai una richiesta di supporto","Indica un limite sicuro"],cue:["Dopo aver verificato la mia responsabilità","Al segnale già scelto per la difficoltà"],place:["In un messaggio privato sicuro","Dove ricevo supporto da persone fidate"],fallback:["Cerca supporto prima di contatti rischiosi","Correggi in sicurezza senza confidarti"],observation:["I fatti e la strada scelta","Come ho rimediato o mi sono protetto"],minutes:[2,1,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Prendo la vergogna come prova di aver causato danni",stop:"La vergogna non ti impone scuse, perdono o contatti rischiosi. Cerca protezione se c’è pericolo.",accessible:"Tieni privata la riflessione. Usa parole neutre, scrivi, usa la lingua dei segni o chiedi assistenza. Confidarti e concentrarti sul corpo sono facoltativi.",result:"Hai fatto il passo adatto che avevi scelto?",observation:"Quale responsabilità emergeva dai fatti e che cosa hai fatto davvero?",scenario:{scenario:"Un collega prende in giro Irene davanti agli altri dopo una sua osservazione corretta. Lei si vergogna. I fatti non indicano un errore o un danno causato da lei.",question:"Quale prossimo passo è adatto?",options:[{text:"Scusarsi per aver contribuito alla tensione, così il collega avrà la possibilità di rispondere in modo più costruttivo.",feedback:"Rimediare presuppone una responsabilità reale. Qui per Irene non emerge. Le scuse inventerebbero una colpa e nasconderebbero la derisione. Può invece valutare un supporto adatto o un limite sicuro, senza attribuirsi danni inesistenti.",id:"apologize-tension"},{text:"Ricordarsi che tutti hanno giornate difficili e lasciar perdere l’episodio per cercare di preservare il rapporto di lavoro.",feedback:"L’umanità condivisa non giustifica un trattamento dannoso né risolve la scelta di sicurezza. Irene può considerare il contesto mentre cerca supporto appropriato. Non è obbligata ad affrontare il collega direttamente.",id:"normalize-and-ignore"},{text:"Riconoscere la vergogna, tenere chiari i fatti e scegliere supporto sicuro o un limite, senza inventare un errore.",feedback:"La vergogna non dimostra colpevolezza. Irene può affrontare la derisione per una via sicura, senza scusarsi per un errore inesistente o dimostrare di meritare rispetto prima di chiedere aiuto a qualcuno.",id:"support-not-blame"}],id:"compassion-5-imposed-shame",bestOptionId:"support-not-blame"},takeaway:"Le sensazioni meritano cura. La responsabilità richiede fatti. Scegli rimedi, protezione o supporto.",follow:"I fatti richiedevano di rimediare, proteggerti, cercare supporto pratico o chiedere altri chiarimenti?",followObservation:"Indica la strada scelta e il passo fatto, senza rivelare dettagli che vuoi tenere privati.",depth:[{heading:"Vergogna e senso di colpa descrivono tendenze",paragraphs:["Tangney e colleghi hanno esaminato emozioni morali e comportamenti, soprattutto attraverso ricerche osservative. La vergogna rivolta all’intera persona era spesso legata al ritirarsi o difendersi; il senso di colpa rivolto al comportamento poteva accompagnare empatia e riparazione. Contesto e misure contano. La revisione non stabilisce che la vergogna sia sempre distruttiva o il senso di colpa sempre utile. Anche un senso di colpa eccessivo o alimentato dal rimuginio può nuocere. [C08: compassion-tangney-moral-emotions]","La vergogna può seguire abusi, esclusione, discriminazione o malattia senza che chi la prova abbia agito male. Non trasformarla in una frase di colpevolezza solo per adattarti a un esercizio sul rimediare. Individua prima un comportamento reale e le sue conseguenze. Scuse proporzionate possono servire per un danno causato, senza pretendere rassicurazioni o perdono. Se la colpa ti viene imposta, possono servire meglio supporto e protezione. Cambiare una frase non dimostra un passaggio causale dalla vergogna a un senso di colpa utile, né prova che hai rimediato."]},{heading:"Confidarti resta facoltativo e deve essere sicuro",paragraphs:["Brown ha sviluppato la teoria della resilienza alla vergogna attraverso interviste a 215 donne. Riconoscere vergogna e fattori scatenanti, verificare le aspettative, cercare legami sicuri e dare un nome alla vergogna appartengono a questa cornice qualitativa e pratica. La fonte non documenta uno studio controllato che testi la sequenza in quattro passi come trattamento, né dimostra che l’obbligo di confidarsi migliori i risultati. [C09: compassion-brown-shame-resilience]","Usa gli elementi utili alla prossima scelta, senza dover ricordare traumi, esaminare il corpo o raccontare una storia. Una persona sicura e disponibile può aiutare, ma potrebbe non esserci. Riflessione privata, richiesta di supporto professionale, correzione basata sui fatti o limite protettivo sono alternative. Non confidarti con chi abusa di te o potrebbe usare le informazioni contro di te. Una vergogna persistente o opprimente merita supporto qualificato. La prova chiede quale azione adatta hai fatto e che cosa ha mostrato la risposta, non se hai nominato ogni sensazione o seguito una sequenza prescritta."]}],id:"compassion-5",sources:["compassion-tangney-moral-emotions","compassion-brown-shame-resilience"]}),d=a({title:"Un altro appunto gentile? Fai seguire un cambiamento",goal:"Rivedi i tentativi della stessa prova e fai un passo fattibile per rimediare, proteggerti o chiedere supporto.",hook:"Scriverti parole gentili può aiutare. Quale cambiamento utile ti suggerirebbero oggi?",reason:"Quale cambiamento rimanderebbe un altro appunto?",reasons:["Portare avanti un rimedio concreto","Proteggere un limite fattibile","Usare supporto invece di attaccarmi"],paragraphs:["L’autrice propone di scrivere dal punto di vista di un amico premuroso, offrendo cura e suggerimenti per cambiare. Quindici minuti non sono una durata ottimale verificata. Lo studio sul programma non isolava la lettera né manteneva un gruppo di confronto a un anno.","Rivedi le annotazioni dello stesso schema. Quale risposta ha portato a rimediare, proteggerti, lavorare o chiedere supporto? Mantieni ciò che ha aiutato e cambia un ostacolo. Un appunto facoltativo può indicare verità, contesto, cura e un passo adatto. Fallo se appropriato; scegli la prossima occasione realistica. Non servono calore, perdono o una serie di tentativi senza interruzioni."],example:{title:"Rosa sceglie la prossima versione fattibile",text:"Domenica alle 19 Rosa rivede le annotazioni sulle lettere amministrative che evita. Un breve appunto basato sui fatti ha aiutato; ripassare a lungo le autocritiche no. Al tavolo della cucina scrive quattro frasi di cura, corregge un errore di archiviazione e chiede aiuto per un avviso poco chiaro. La pila resta. Mantiene il minimo utile per mercoledì, senza promettersi sollievo immediato."},invitation:"Rivedi la stessa prova. Mantieni ciò che aiuta, cambia un ostacolo e fai un passo adatto.",instructions:["Usa i tentativi reali; non supporre gli esiti mancanti.","Fai qualcosa di concreto per rimediare, proteggerti, lavorare o chiedere supporto."],suggestions:{action:["Correggi il prossimo punto da sistemare","Usa il limite protettivo già provato","Invia la richiesta specifica di supporto"],minimum:["Correggi un elemento concreto","Indica un limite fattibile","Fai una richiesta specifica"],cue:["Dopo aver rivisto i miei tentativi reali","Al prossimo segnale già provato e utile"],place:["Al tavolo della cucina","Nel mio canale sicuro di supporto"],fallback:["Chiedi aiuto per affrontare l’ostacolo","Riduci il passo o sospendilo consapevolmente"],observation:["Il passo e il supporto usati davvero","Che cosa ho mantenuto o cambiato"],minutes:[3,2,5],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1}]},obstacle:"Mi consolo scrivendo e rimando il cambiamento utile",stop:"Interrompi ricordi dolorosi o scrittura se provi disagio. Rimediare richiede responsabilità reale; potrebbe invece servire protezione.",accessible:"La lettera è facoltativa. Usa quattro frasi neutre in silenzio, scrivi, usa la lingua dei segni o chiedi aiuto. Non serve calore.",result:"Hai fatto il passo pratico che avevi scelto?",observation:"Che cosa hai mantenuto, cambiato o chiesto? Che cosa è successo davvero?",scenario:{scenario:"Rosa ha controllato il bilancio: un prestito userebbe i soldi per le necessità di questa settimana. Nessuno sta chiedendo un prestito adesso. Può mettere da parte quei soldi oggi, senza contattare qualcuno.",question:"A che cosa deve portare questa revisione?",options:[{text:"Scrivere un rifiuto gentile ma chiaro per la prossima richiesta, lasciando disponibili i soldi di oggi fino a quell’occasione.",feedback:"Scrivere un rifiuto prepara un limite futuro. Lascia disponibili oggi i soldi per un prestito. Può metterli da parte adesso e annotare come azione separata qualsiasi comunicazione che farà più avanti.",id:"draft-future-refusal"},{text:"Mettere da parte oggi la somma per le necessità e preparare un limite sicuro per eventuali richieste future.",feedback:"Mettere da parte i soldi cambia la disponibilità per prestiti oggi. Scrivere il limite o provare il messaggio è soltanto preparazione. Non servono contatti immediati né una promessa di sentirsi meglio.",id:"reserve-essential-funds"},{text:"Rivedere il bilancio con una persona fidata che può aiutarla prima di decidere quale limite mettere ai prestiti.",feedback:"Il supporto aiuta se sostenibilità o sicurezza sono incerte. Rosa sa già che intaccherebbe le necessità e può proteggere quei soldi oggi. Può poi chiedere aiuto per gestire le richieste future.",id:"budget-and-support"}],id:"compassion-6-boundary-after-review",bestOptionId:"reserve-essential-funds"},takeaway:"Lascia che la cura dica la verità. Usa le annotazioni per adattare il prossimo passo.",follow:"Quale strada pratica ha preso la nuova versione? Quale condizione merita di essere ripetuta?",followObservation:"Indica che cosa hai fatto; un limite scritto resta preparazione finché non lo usi.",depth:[{heading:"La lettera facoltativa sostiene una scelta concreta",paragraphs:["Le indicazioni di Neff sulla lettera invitano a prendere il punto di vista di un amico che conosce qualità, debolezze e circostanze. Includono suggerimenti gentili per cambiare e il mettere la lettera da parte per rileggerla. La pagina descrive un esercizio, non una verifica isolata di efficacia o una durata convalidata di quindici minuti. [C17: compassion-letter-guidance] L’opzione di quattro frasi e il passo pratico successivo sono adattamenti ODA.","Se scrivi, scegli una difficoltà quotidiana gestibile. Non servono un inventario di insicurezze, un racconto di sofferenza, calore incondizionato o un amico disponibile. Basta un rispetto sobrio: indica la verità, il contesto rilevante, una cura utile e l’azione adatta. Rimediare riguarda la responsabilità reale; protezione serve dove occorrono un limite o sicurezza. Una lettera completata può essere annotata come preparazione. Correzione concreta e richiesta di supporto hanno un proprio minimo. Un limite scritto sui prestiti resta preparazione finché i soldi non vengono riservati o il limite usato in un’occasione sicura."]},{heading:"Usa le annotazioni per decidere che cosa fare la prossima settimana",paragraphs:["Neff parla di compassione tenera e ferma per descrivere forme pratiche di cura: conforto e accettazione, insieme a protezione, limiti e perseguimento degli obiettivi. Non sono sistemi cerebrali dimostrati autonomamente. [C11: compassion-neff-definition] Usa queste parole soltanto se aiutano a esaminare lo schema reale. Un appunto confortante che rinvia un cambiamento necessario e un piano severo che ignora le tue possibilità possono entrambi richiedere modifiche.","Lo studio Mindful Self-Compassion confrontava un programma completo di otto settimane con una lista d’attesa. La verifica incompleta a un anno non aveva un gruppo di controllo contemporaneo: non dimostra un effetto duraturo della lettera. [C05: compassion-mindful-self-compassion-rct] Per questo concludi usando i tentativi che hai riferito davvero. Mantieni una risposta utile, cambia un ostacolo e scegli la prossima occasione con una data. Non devi aggiungere un rito o compensare una pausa. Se servono ancora risorse, assistenza o supporto professionale, riconosci quel bisogno. Finire il corso non prova che hai rimediato, trovato sollievo o fatto pratica. Lascia che la prossima annotazione mostri ciò che è successo."]}],id:"compassion-6",sources:["compassion-letter-guidance","compassion-neff-definition","compassion-mindful-self-compassion-rct"]}),v=[{id:"compassion-1",practiceCount:3,correct:0,photo:{id:"1474418397713-7ede21d49118",alt:"Una persona seduta su una roccia guarda il sole sorgere sulle montagne"}},{id:"compassion-2",practiceCount:3,correct:0,photo:{id:"1529156069898-49953e39b3ac",alt:"Amici seduti con le braccia sulle spalle degli altri, visti da dietro"}},{id:"compassion-3",practiceCount:3,correct:0,photo:{id:"1499209974431-9dddcece7f88",alt:"Una persona apre le braccia verso il sole al tramonto"}},{id:"compassion-4",practiceCount:3,correct:0,photo:{id:"1441974231531-c6227db76b6e",alt:"Luce del sole tra gli alberi di un bosco tranquillo"}},{id:"compassion-5",practiceCount:3,correct:0,photo:{id:"1544027993-37dbfe43562a",alt:"Due mani si tendono l’una verso l’altra"}},{id:"compassion-6",practiceCount:3,correct:0,photo:{id:"1455390582262-044cdead277a",alt:"Una mano scrive su un quaderno con una penna"}}];function f(i,e){const o=v[e],r=i.judgment.primary.options.find(t=>t.id===i.judgment.primary.bestOptionId),n=i.judgment.primary.options.filter(t=>t.id!==r.id).map(t=>t.text);return n.splice(o.correct,0,r.text),{id:o.id,schemaVersion:2,v2:i,title:i.title,minutes:i.minutes.learning,goal:i.goal,reading:i.idea.paragraphs,deeper:i.goDeeper.sections,example:i.idea.example,practice:[i.move.instructions[0],i.move.suggested.action,"Annota l’esito reale e scegli il prossimo tentativo appropriato."].slice(0,o.practiceCount),reflection:i.direction.reason.label,question:`${i.judgment.primary.scenario} ${i.judgment.primary.question}`,options:n,correct:o.correct,feedback:r.feedback,takeaway:i.carry.takeaway,sources:i.goDeeper.sourceIds,photo:o.photo}}const h={id:"compassion",title:"Un errore? Affrontalo senza insultarti",subtitle:"6 lezioni. Affronta una difficoltà con rimedi, protezione o supporto, senza pretendere di sentirti più affettuoso.",description:"Quando qualcosa va storto, affronta i fatti senza disprezzarti. Segui una difficoltà ricorrente, verifica le tue responsabilità e scegli come rimediare, proteggerti o chiedere supporto.",scope:"Per adulti che si trattano con durezza dopo errori, difficoltà o momenti dolorosi. È educazione e pratica personale, non terapia. Se vivi con traumi, abusi o una vergogna persistente o opprimente, rivolgiti a un professionista qualificato. Gli esercizi di compassione verso di sé possono talvolta risvegliare vecchi dolori. In caso di crisi o pensieri di farti del male, contatta subito il numero di emergenza locale.",outcome:"Una risposta equa a una difficoltà ricorrente, un’azione appropriata per rimediare o proteggerti e un prossimo tentativo fattibile.",photo:{id:"1470252649378-9c29740c9fa8",alt:"Un campo tranquillo nella luce calda della sera"},lang:"it",lessons:[s,l,c,p,u,d].map(f)},b=Object.freeze(Object.defineProperty({__proto__:null,COMPASSION_1_V2:s,COMPASSION_2_V2:l,COMPASSION_3_V2:c,COMPASSION_4_V2:p,COMPASSION_5_V2:u,COMPASSION_6_V2:d,COURSE:h,SOURCES:g},Symbol.toStringTag,{value:"Module"}));export{b as c};
